// Optional Live LinkedIn Voyager API Executor (only marks "✅ Sent on LinkedIn (API Verified)" when li_at succeeds!)
async function tryVoyagerExecute(cookie, actType, postUrl, reactionLabel, commentText) {
  if (!cookie || cookie.length < 20) {
    return { ok: false, status: '⏳ Approved — Tap Link to Send (Set li_at for Auto)' };
  }
  const urnMatch = String(postUrl || '').match(/activity[:-](\d{18,20})|ugcPost[:-](\d{18,20})/i);
  if (!urnMatch) {
    return { ok: false, status: '⏳ Approved — Tap Profile/Post Link to Send' };
  }
  const actIdNum = urnMatch[1] || urnMatch[2];
  const threadUrn = `urn:li:activity:${actIdNum}`;
  const csrf = 'ajax:8841920394810293841';
  const headers = {
    'Cookie': `li_at=${cookie}; JSESSIONID="${csrf}"`,
    'csrf-token': csrf,
    'x-restli-protocol-version': '2.0.0',
    'Content-Type': 'application/json',
    'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36'
  };
  try {
    if (reactionLabel && reactionLabel !== '—') {
      const rMap = { 'Insightful': 'INTEREST', 'Support': 'EMPATHY', 'Celebrate': 'PRAISE', 'Like': 'LIKE' };
      const rType = rMap[reactionLabel] || 'LIKE';
      await _ctx.helpers.httpRequest({
        method: 'POST',
        url: `https://www.linkedin.com/voyager/api/feed/normReactions?threadUrn=${encodeURIComponent(threadUrn)}`,
        headers,
        body: { reactionType: rType },
        json: true,
        timeout: 5000
      });
    }
    if (actType === 'Post Comment' && commentText) {
      await _ctx.helpers.httpRequest({
        method: 'POST',
        url: 'https://www.linkedin.com/voyager/api/feed/normComments',
        headers,
        body: {
          commentary: { text: commentText, attributes: [] },
          threadUrn
        },
        json: true,
        timeout: 5000
      });
    }
    return { ok: true, status: '✅ Sent on LinkedIn (API Verified)' };
  } catch (e) {
    return { ok: false, status: '⏳ Approved — Tap Link to Send (li_at Expired/Needs 1-Tap)' };
  }
}

