function buildShortHumanFhNote(personName, companyName, category) {
  const first = String(personName || 'there').split(' ')[0];
  const comp = String(companyName || 'your team').split('/')[0].replace(/\(.*?\)/g, '').trim() || 'your team';
  const catUpper = String(category || '').toUpperCase();
  if (catUpper.includes('HR') || catUpper.includes('RECRUIT') || catUpper.includes('TALENT')) {
    return `Hi ${first}, closely following ${comp}'s analytics hiring—would love to connect!`;
  }
  if (catUpper.includes('MANAGER') || catUpper.includes('PARTNER') || catUpper.includes('INSIDER') || catUpper.includes('REFERRAL')) {
    return `Hi ${first}, admire your analytics leadership at ${comp}—would love to connect!`;
  }
  return `Hi ${first}, great seeing your analytics work at ${comp}—would love to connect!`;
}

